import os
import numpy as np

# ==========================================
# Directory Configuration
# ==========================================
INPUT_DIR = "./input"
METADATA_DIR = "./metadata"
WORKING_DIR = "./working/idea_26"
SUBMISSION_DIR = "./submission"

# Ensure necessary writable directories exist
os.makedirs(WORKING_DIR, exist_ok=True)
os.makedirs(SUBMISSION_DIR, exist_ok=True)

# ==========================================
# File Path Configuration
# ==========================================
# Metadata files generated by the metadata script
TRAIN_DATA_PATH = os.path.join(METADATA_DIR, "train.csv")
VAL_DATA_PATH = os.path.join(METADATA_DIR, "val.csv")
TEST_DATA_PATH = os.path.join(METADATA_DIR, "test.csv")

# Raw input files
SAMPLE_SUBMISSION_PATH = os.path.join(INPUT_DIR, "sample_submission.csv")

# Output files
SUBMISSION_FILE_PATH = os.path.join(SUBMISSION_DIR, "submission.csv")

# ==========================================
# Data Configuration
# ==========================================
ID_COL = "id"
TARGET_COL = "species"

# Semantic Feature Groups for Factorized Modeling
# These prefixes are used to slice the 192-column feature set into 3 groups of 64
FEATURE_PREFIXES = ["margin", "shape", "texture"]

# Numerical Precision
# Using float64 is critical for the stability of covariance estimation
# and logit aggregation in the OAS-LDA backbone.
NUMERIC_DTYPE = np.float64

# ==========================================
# Reproducibility
# ==========================================
SEED = 42


def set_seed(seed=SEED):
    """
    Sets the random seed for reproducibility across numpy and python random.
    """
    import random
    import numpy as np

    random.seed(seed)
    np.random.seed(seed)
    os.environ["PYTHONHASHSEED"] = str(seed)


# Initialize seed immediately
set_seed(SEED)
